<script setup lang="ts">
import{computed,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{state,login}from'../store';import{api,run}from'../api';import Icon from'../components/Icon.vue';import type{FormInstance,FormRules}from'element-plus'
const route=useRoute(),router=useRouter(),mode=ref<'login'|'register'>('login'),busy=ref(false),formRef=ref<FormInstance>(),form=reactive({username:'',password:'',name:'',email:'',studentNo:'',department:''})
const rules=computed<FormRules>(()=>({username:[{required:true,message:'请输入用户名',trigger:'blur'},...(mode.value==='register'?[{pattern:/^[a-zA-Z0-9_]{3,32}$/,message:'请输入 3–32 位字母、数字或下划线',trigger:'blur'}]:[])],password:[{required:true,message:'请输入密码',trigger:'blur'},{min:8,max:64,message:'密码长度为 8–64 位',trigger:'blur'}],name:[{required:true,message:'请输入姓名',trigger:'blur'}],email:[{required:true,message:'请输入邮箱',trigger:'blur'},{type:'email',message:'请输入有效邮箱',trigger:'blur'}],studentNo:[{required:true,message:'请输入学号',trigger:'blur'}],department:[{required:true,message:'请输入院系',trigger:'blur'}]}))
async function submit(){if(!await formRef.value?.validate().catch(()=>false))return;busy.value=true;await run(async()=>{if(mode.value==='register')await api('/auth/register','POST',form);await login(form.username,form.password);const redirect=String(route.query.redirect||'/');router.replace(redirect.startsWith('/')&&!redirect.startsWith('//')?redirect:'/')},mode.value==='login'?'欢迎回到 CampusHub':'注册成功，开始探索校园吧');busy.value=false}
function demo(role:string){mode.value='login';form.username=role;form.password='CampusHub@2026';formRef.value?.clearValidate()}
</script>
<template><div class="page-content auth-page"><div class="auth-visual"><img src="/images/campus.jpg" alt="大学校园"><div class="auth-visual-copy"><Icon name="graduation" :size="44"/><span>每一种热爱，都能找到归属</span><h1>你的热爱，<br>在这里相遇。</h1><p>每一段值得纪念的大学时光，<br>都从勇敢迈出的第一步开始。</p><div class="auth-visual-footer">让校园生活，拥有更多可能。<Icon name="sparkles" :size="22"/></div></div></div><div class="auth-form-panel"><span class="eyebrow">欢迎加入校园社团社区</span><h2>{{mode==='login'?'欢迎回到校园':'开启你的校园故事'}}</h2><p>{{mode==='login'?'登录账号，与热爱重新连接。':'填写个人信息，加入我们的校园社区。'}}</p><div class="auth-tabs"><button :class="{active:mode==='login'}" @click="mode='login';formRef?.clearValidate()">账号登录</button><button :class="{active:mode==='register'}" @click="mode='register';formRef?.clearValidate()">注册账号</button></div><el-form ref="formRef" :model="form" :rules="rules" label-position="top" @submit.prevent="submit"><el-form-item label="用户名" prop="username"><el-input v-model="form.username" autocomplete="username" maxlength="32" placeholder="请输入用户名" size="large"/></el-form-item><template v-if="mode==='register'"><div class="form-grid"><el-form-item label="姓名" prop="name"><el-input v-model="form.name" maxlength="50" placeholder="你的姓名"/></el-form-item><el-form-item label="学号" prop="studentNo"><el-input v-model="form.studentNo" maxlength="30" placeholder="你的学号"/></el-form-item></div><el-form-item label="邮箱" prop="email"><el-input v-model="form.email" type="email" autocomplete="email" maxlength="120" placeholder="用于联系的邮箱"/></el-form-item><el-form-item label="院系" prop="department"><el-input v-model="form.department" maxlength="100" placeholder="例如：计算机与人工智能学院"/></el-form-item></template><el-form-item label="密码" prop="password"><el-input v-model="form.password" type="password" show-password :autocomplete="mode==='login'?'current-password':'new-password'" maxlength="64" placeholder="请输入至少 8 位密码" size="large"/></el-form-item><el-button native-type="submit" type="primary" size="large" class="full-width auth-submit" :loading="busy">{{mode==='login'?'登录，开启校园生活':'注册并开始探索'}}<Icon name="arrow" :size="18"/></el-button></el-form><div v-if="state.overview.demoEnabled" class="demo-accounts"><span>本地演示 · 点击填入账号</span><div><el-button @click="demo('student')">学生账号</el-button><el-button @click="demo('admin')">管理员账号</el-button></div><small>演示密码：CampusHub@2026</small></div><p class="auth-footnote"><Icon name="shield" :size="14"/>密码加密存储，安全连接你的校园生活。</p></div></div></template>
